/**
 * Tackle Design System - TypeScript Token Types
 * Type-safe design tokens for TypeScript projects
 */

// ============================================
// Color Types
// ============================================

export type RedScale = 10 | 20 | 30 | 40 | 50 | 70 | 90;
export type YellowScale = 10 | 20 | 30 | 40 | 50 | 70 | 90;
export type GreenScale = 10 | 20 | 30 | 40 | 50 | 70 | 90;
export type BlueScale = 10 | 20 | 30 | 40 | 50 | 70 | 90;
export type PurpleScale = 10 | 20 | 30 | 40 | 50 | 70 | 90;
export type TealScale = 90 | 100;
export type NeutralScale = 0 | 10 | 20 | 40 | 50 | 60 | 70 | 90 | 100 | 1000;

export interface ColorToken {
  value: string;
  type: 'color';
}

export interface ColorPalette {
  red: Record<RedScale, ColorToken>;
  yellow: Record<YellowScale, ColorToken>;
  green: Record<GreenScale, ColorToken>;
  blue: Record<BlueScale, ColorToken>;
  purple: Record<PurpleScale, ColorToken>;
  teal: Record<TealScale, ColorToken>;
  neutral: Record<NeutralScale, ColorToken>;
}

export type SemanticColor = 'primary' | 'success' | 'warning' | 'error' | 'info';
export type TextColor = 'primary' | 'secondary' | 'disabled' | 'link' | 'linkHover';
export type BackgroundColor = 'primary' | 'secondary' | 'tertiary';

// ============================================
// Spacing Types
// ============================================

export type SpacingScale = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

export interface SpacingToken {
  value: string;
  type: 'spacing';
}

export interface SpacingTokens {
  spacing: Record<SpacingScale, SpacingToken>;
  gap: {
    grid: SpacingToken;
  };
  padding: {
    container: {
      horizontal: SpacingToken;
      vertical: SpacingToken;
    };
  };
}

// ============================================
// Typography Types
// ============================================

export type FontSize = 'hero' | 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'body' | 'small';
export type FontWeight = 'light' | 'regular' | 'semibold' | 'bold';
export type FontFamily = 'primary' | 'code';

export interface FontToken {
  value: string;
  type: 'fontFamily' | 'fontSize' | 'fontWeight' | 'lineHeight';
}

export interface TypographyTokens {
  fontFamily: Record<FontFamily, FontToken>;
  fontSize: Record<FontSize, FontToken>;
  fontWeight: Record<FontWeight, FontToken>;
  lineHeight: Record<FontSize, FontToken>;
}

// ============================================
// Elevation Types
// ============================================

export type ElevationLevel = 100 | 200 | 300 | 400 | '500L' | '500R';

export interface ElevationToken {
  value: string;
  type: 'boxShadow';
  description: string;
}

export interface ElevationTokens {
  elevation: Record<ElevationLevel, ElevationToken>;
  borderRadius: {
    base: {
      value: string;
      type: 'borderRadius';
    };
  };
}

// ============================================
// Layout Types
// ============================================

export type HeaderType = 'global' | 'page';
export type PanelType = 'left' | 'rightNarrow' | 'rightWide';
export type GridColumns = 2 | 3 | 4 | 6;
export type Breakpoint = 'mobile' | 'tablet' | 'desktop';

export interface SizingToken {
  value: string;
  type: 'sizing' | 'number' | 'breakpoint';
}

export interface LayoutTokens {
  layout: {
    header: Record<HeaderType | 'toolbar', SizingToken>;
    panel: {
      left: SizingToken;
      right: {
        narrow: SizingToken;
        wide: SizingToken;
      };
    };
  };
  grid: {
    columns: Record<GridColumns, SizingToken>;
  };
  breakpoint: Record<Breakpoint, SizingToken>;
}

// ============================================
// Icon Types
// ============================================

export type IconSize = 'small' | 'medium' | 'large' | 'xl';

export interface IconTokens {
  iconSize: Record<IconSize, SizingToken>;
}

// ============================================
// Complete Token System
// ============================================

export interface DesignTokens {
  color: ColorPalette;
  spacing: SpacingTokens['spacing'];
  gap: SpacingTokens['gap'];
  padding: SpacingTokens['padding'];
  typography: TypographyTokens;
  elevation: ElevationTokens['elevation'];
  borderRadius: ElevationTokens['borderRadius'];
  layout: LayoutTokens['layout'];
  grid: LayoutTokens['grid'];
  breakpoint: LayoutTokens['breakpoint'];
  iconSize: IconTokens['iconSize'];
}

// ============================================
// Helper Types for Component Usage
// ============================================

export interface ThemeColors {
  red: Record<RedScale, string>;
  yellow: Record<YellowScale, string>;
  green: Record<GreenScale, string>;
  blue: Record<BlueScale, string>;
  purple: Record<PurpleScale, string>;
  teal: Record<TealScale, string>;
  neutral: Record<NeutralScale, string>;
  primary: string;
  success: string;
  warning: string;
  error: string;
  info: string;
}

export interface ThemeSpacing {
  xs: string;
  sm: string;
  md: string;
  lg: string;
  xl: string;
}

export interface ThemeTypography {
  fontFamily: {
    primary: string;
    code: string;
  };
  fontSize: Record<FontSize, string>;
  fontWeight: Record<FontWeight, string>;
  lineHeight: Record<FontSize, string>;
}

export interface ThemeElevation {
  100: string;
  200: string;
  300: string;
  400: string;
  '500L': string;
  '500R': string;
}

export interface Theme {
  colors: ThemeColors;
  spacing: ThemeSpacing;
  typography: ThemeTypography;
  elevation: ThemeElevation;
  borderRadius: {
    base: string;
  };
  breakpoints: Record<Breakpoint, string>;
  iconSize: Record<IconSize, string>;
}
